import React, { useMemo } from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  spring,
  interpolate,
  interpolateColors,
} from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type MinimalNightDayProps = Record<string, any>;

// Deterministic pseudo-random number generator for stars
const pseudoRandom = (seed: number) => {
  const x = Math.sin(seed) * 10000;
  return x - Math.floor(x);
};

const MinimalNightDay: React.FC<MinimalNightDayProps> = ({
  backgroundColor = "#0f172a",
  dayBackgroundColor = "#e0f2fe",
  transparentBackground = false,
  durationInSeconds = 8,
  moonColor = "#fef08a",
  sunColor = "#f59e0b",
  iconSize = 240,
  starCount = 40,
}) => {
  {/* Load Google Fonts */}
  useFontLoader(["Inter"]);
  {/* End Load Google Fonts */}

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Timing constants
  const totalFrames = durationInSeconds * fps;
  const moonSetStart = Math.floor(totalFrames * 0.35);
  const bgChangeStart = Math.floor(totalFrames * 0.40);
  const sunRiseStart = Math.floor(totalFrames * 0.45);
  const bgChangeEnd = Math.floor(totalFrames * 0.60);

  // Springs
  const moonRiseSpring = spring({
    frame,
    fps,
    config: { damping: 14, mass: 0.8 },
  });

  const moonSetSpring = spring({
    frame: frame - moonSetStart,
    fps,
    config: { damping: 14, mass: 0.8 },
  });

  const sunRiseSpring = spring({
    frame: frame - sunRiseStart,
    fps,
    config: { damping: 14, mass: 0.8 },
  });

  // Positions
  const offscreenY = height + iconSize;
  const targetY = height * 0.45;
  const dist = offscreenY - targetY;

  const moonY = offscreenY - moonRiseSpring * dist + moonSetSpring * dist;
  const sunY = offscreenY - sunRiseSpring * dist;

  // Rotations & Effects
  const sunRotation = interpolate(
    frame,
    [sunRiseStart, totalFrames],
    [0, 90],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const starGlobalOpacity = interpolate(
    frame,
    [bgChangeStart, bgChangeEnd],
    [1, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // Background Color Interpolation
  const interpolatedBgColor = interpolateColors(
    frame,
    [bgChangeStart, bgChangeEnd],
    [backgroundColor, dayBackgroundColor]
  );

  // Parser-safe background definition
  const finalBgColor = transparentBackground ? "transparent" : interpolatedBgColor;

  // Generate deterministic stars
  const stars = useMemo(() => {
    return Array.from({ length: starCount }).map((_, i) => ({
      id: i,
      x: pseudoRandom(i * 10) * 100, // percentage
      y: pseudoRandom(i * 10 + 1) * 70, // percentage (top 70%)
      size: pseudoRandom(i * 10 + 2) * 4 + 2, // 2px to 6px
      blinkOffset: pseudoRandom(i * 10 + 3) * Math.PI * 2,
    }));
  }, [starCount]);

  return (
    <AbsoluteFill
      style={{
        backgroundColor: finalBgColor,
        fontFamily: "Inter",
        overflow: "hidden",
        transition: "none",
      }}
    >
      {/* Stars Background */}
      {stars.map((star) => {
        const blinkOpacity = interpolate(
          Math.sin(frame / 10 + star.blinkOffset),
          [-1, 1],
          [0.3, 1]
        );
        return (
          <div
            key={star.id}
            style={{
              position: "absolute",
              left: `${star.x}%`,
              top: `${star.y}%`,
              width: star.size,
              height: star.size,
              backgroundColor: "white",
              borderRadius: "50%",
              opacity: starGlobalOpacity * blinkOpacity,
              transition: "none",
            }}
          />
        );
      })}

      {/* Moon */}
      <div
        style={{
          position: "absolute",
          left: width / 2,
          top: moonY,
          transform: `translate(-50%, -50%)`,
          width: iconSize,
          height: iconSize,
          transition: "none",
        }}
      >
        <svg
          width="100%"
          height="100%"
          viewBox="0 0 100 100"
          overflow="visible"
          style={{ transition: "none" }}
        >
          <defs>
            <mask id="moon-mask">
              <rect x="0" y="0" width="100" height="100" fill="white" />
              <circle cx="70" cy="30" r="35" fill="black" />
            </mask>
          </defs>
          <circle
            cx="50"
            cy="50"
            r="40"
            fill={moonColor}
            mask="url(#moon-mask)"
          />
        </svg>
      </div>

      {/* Sun */}
      <div
        style={{
          position: "absolute",
          left: width / 2,
          top: sunY,
          transform: `translate(-50%, -50%)`,
          width: iconSize,
          height: iconSize,
          transition: "none",
        }}
      >
        <svg
          width="100%"
          height="100%"
          viewBox="0 0 100 100"
          overflow="visible"
          style={{ transition: "none" }}
        >
          <circle cx="50" cy="50" r="22" fill={sunColor} />
          <g transform={`rotate(${sunRotation} 50 50)`}>
            {[0, 45, 90, 135, 180, 225, 270, 315].map((angle, i) => (
              <line
                key={i}
                x1="50"
                y1="8"
                x2="50"
                y2="18"
                stroke={sunColor}
                strokeWidth="6"
                strokeLinecap="round"
                transform={`rotate(${angle} 50 50)`}
              />
            ))}
          </g>
        </svg>
      </div>
    </AbsoluteFill>
  );
};

export default MinimalNightDay;